"""Publish the audited ACORD retest and an explicitly weighted six-task index.

The original matrix, correction and five-task paired evidence are immutable.
"""
import json,statistics,csv,re
import build_matrix as previous
R=previous.ROOT; A=previous.A; ORDER=previous.ORDER; FIVE=previous.FIVE
LEGAL=json.loads((R/'data/acord/retest.json').read_text('utf8'))
tab=previous.tab
def t(z,e,lang):return e if lang else z
def name(k,lang):return previous.name(k,lang)
def combo(r,lang):return previous.combo(r,lang)
def group(scope):
 ids=ORDER if scope=='all' else FIVE if scope=='general' else ORDER[:3] if scope=='mlqa' else [scope]
 source=[r for r in A['rows'] if r['dataset']!='acord-eng-eng']+LEGAL['rows']
 groups={}
 for r in source:
  if r['dataset'] in ids:groups.setdefault((r['embedding'],r['reranker']),[]).append(r)
 result=[]
 for (e,rr),rows in groups.items():
  assert len(rows)==len(ids)
  if len(ids)==1:result.append(dict(rows[0]));continue
  r={'embedding':e,'reranker':rr,'queries':sum(x['queries'] for x in rows),'datasets':len(ids),'weight_gib_sum':rows[0]['weight_gib_sum']}
  for k in ['ndcg10','top1','mrr10','recall50','judged_coverage50']:r[k]=statistics.mean(x[k] for x in rows)
  r.update(total_ms_mean=None if scope=='all' else statistics.mean(x['total_ms_mean'] for x in rows),total_ms_p50=None,total_ms_p95=None)
  result.append(r)
 return sorted(result,key=lambda r:-r['ndcg10'])
def pick(e,rr,scope='all'):return next(r for r in group(scope) if r['embedding']==e and r['reranker']==rr)
def page(path,title,body,lang):
 s=previous.old.page(path,title,body,lang)
 s=s.replace('中英檢索實驗室','地端RAG中英檢索模型實測').replace('Bilingual Retrieval Lab','Local RAG Retrieval Benchmark').replace('最新測量完成：','最新結果更新：').replace('Latest measurements completed:','Results updated:')
 s=s.replace('14,478','73,164').replace('2026-10-24 01:47','2026-10-28').replace('24 Oct 2026, 01:47','28 Oct 2026')
 return s
def section(title,body,ident=''):return '<section'+(f' id="{ident}"' if ident else '')+'><h2>'+title+'</h2>'+body+'</section>'
def p(text):return '<p>'+text+'</p>'
def home(lang):
 T=lambda z,e:t(z,e,lang);pre='../' if lang else ''
 cards=''
 for e,rr,label in [('qwen-8b','qwen-reranker-4b',T('最高 nDCG 點估計','Highest nDCG estimate')),('qwen-4b','qwen-reranker-0.6b',T('不到 5 GiB 的品質選擇','Quality under 5 GiB')),('bge-m3','qwen-reranker-0.6b',T('不到 1.5 GiB 的均衡選擇','Balance under 1.5 GiB'))]:
  r=pick(e,rr);g=pick(e,rr,'general');l=pick(e,rr,'acord-eng-eng')
  cards+=f'<article class="scorecard"><span>{label}</span><div class="score-number"><strong>{r["ndcg10"]:.3f}</strong><span> / 1.00</span></div><div class="score-meter" role="meter" aria-label="nDCG@10" aria-valuemin="0" aria-valuemax="1" aria-valuenow="{r["ndcg10"]:.6f}"><span style="width:{r["ndcg10"]*100:.3f}%"></span></div><div class="score-scale"><span>0</span><span>{T("滿分 1.00","Maximum 1.00")}</span></div><small>{T("六項基準綜合 nDCG@10","Six-task benchmark nDCG@10")}</small><b>{combo(r,lang)}</b><small>Top-1 {r["top1"]*100:.2f}% · {r["weight_gib_sum"]:.3f} GiB</small><small>{T("一般五項","General five")} {g["ndcg10"]:.3f} · ACORD {l["ndcg10"]:.3f}</small><small>{T("查詢均時：一般五項","Mean query: general five")} {g["total_ms_mean"]/1000:.2f}s · ACORD {l["total_ms_mean"]/1000:.2f}s</small></article>'
 b='<section class="phase-hero"><p class="eyebrow">2026-10-28 · 28 SETUPS · ACORD RETEST VERIFIED</p><h1>'+T('用同一套題目完整比較<br><span class="hero-combinations">28種Embedder X Reranker<span class="keep-phrase">搜尋組合</span></span>','One consistent set of questions.<br>28 Embedder X Reranker setups')+'</h1><p class="lead">'+T('七個 Embedder，搭配不重排或三種重排器。先看六項綜合分數，再按語言、品質與<span class="keep-phrase">模型容量挑選。</span>','Seven embedders, each alone or with three rerankers. Start with the six-task score, then choose by language, quality and model size.')+'</p><div class="headline-scores">'+cards+'</div><p class="macro-note">'+T('nDCG 越接近 1，前十名排序越好；不是回答正確率。六項各占 1/6，法律占 16.7%。ACORD 先排除未標註配對再取候選，與其他項目條件不同；此分數是指定權重的基準指標，不代表真實 RAG 命中率。','Higher nDCG means better top-ten ranking, not answer accuracy. Each task weighs 1/6; legal retrieval contributes 16.7%. ACORD excludes unjudged pairs before selecting candidates, unlike the other tasks. This is a weighted benchmark index, not a production RAG hit rate.')+' <a href="latest-methods.html#average">'+T('平均怎麼算','How averages work')+' →</a></p></section>'
 b+='<div class="evidence-strip">'+''.join('<div><strong>'+v+'</strong><span>'+label+'</span></div>' for v,label in [('28',T('完整受測組合','complete setups')),('6',T('等權測試分項','equal-weight tasks')),('73,164',T('最新逐題結果／168組摘要','current query results / 168 summaries')),('2,613',T('資料集內唯一題目','dataset-qualified queries'))])+'</div><p class="context-line">'+T('原五項 71,568 筆＋ACORD 新測 1,596 筆；同題在28組重複測量，並非73,164個獨立樣本。Q8_0 · M3 Ultra / Metal。','71,568 retained five-task rows + 1,596 new ACORD rows; repeated measurements across setups are not 73,164 independent samples. Q8_0 · M3 Ultra / Metal.')+'</p>'
 findings=[
 (T('小模型配小重排器，仍是省容量的起點。','Small embedders with small rerankers remain a practical starting point.'),T('Qwen 0.6B＋0.6B 的六項 nDCG 為0.859，超過單用 Qwen 8B 的0.833；權重約1.19 GiB。重排需要額外等待，適合容量有限、願意用時間換品質的情境。','Qwen 0.6B + 0.6B scores 0.859 across six tasks, above Qwen 8B alone at 0.833, with about 1.19 GiB of weights. Reranking adds latency: a useful tradeoff when memory is limited.')),
 (T('中文提問，可以直接找到英文資料。','Chinese questions can retrieve English sources directly.'),T('中文查英文中，Qwen 0.6B＋0.6B 的 Top-1 為86.31%，高於 Qwen 8B 單用的81.94%；Qwen 8B＋4B 達92.26%。這是跨語言檢索，不是翻譯品質；未測英文查中文。','Chinese-to-English Top-1 is 86.31% for Qwen 0.6B + 0.6B versus 81.94% for Qwen 8B alone; Qwen 8B + 4B reaches 92.26%. This measures retrieval, not translation; English-to-Chinese was not tested.')),
 (T('法律搜尋，加重排器不一定更好。','Legal retrieval does not always improve with reranking.'),T('Qwen 4B 單用的 ACORD nDCG 為0.703，加 Qwen 0.6B 重排降為0.684，加 BGE 重排為0.675。這項結果提醒我們：百科檢索的推薦，不能直接套用到法律條款。','Qwen 4B alone scores 0.703 on ACORD; Qwen 0.6B reranking lowers it to 0.684, and BGE reranking to 0.675. Recommendations from encyclopedia retrieval do not automatically transfer to legal clauses.')),
 (T('法律最高分接近，仍要看高星等條款。','Leading legal scores are close; high-star clauses still matter.'),T('F2LLM 0.6B＋Qwen 4B 的 ACORD nDCG 最高點估計為0.729，多個4B重排組合約0.726–0.728。領先組的5星正規化 P@5 為44.77%（29題可評）；高品質條款仍難排前面，小差距不代表穩定勝出。','F2LLM 0.6B + Qwen 4B has the highest ACORD estimate at 0.729, while several 4B-reranker setups score about 0.726–0.728. Its normalized 5-star P@5 is 44.77% over 29 eligible queries. High-quality clauses remain difficult; small differences do not establish reliable wins.'))]
 b+=section(T('這次實測的整體結論','Overall conclusions'),'<div class="findings">'+''.join('<article class="finding"><h3>'+h+'</h3>'+p(text)+'</article>' for h,text in findings)+'</div>'+p('<a href="acord.html">'+T('法律檢索完整結果、限制與研究對照','Legal results, limitations and research context')+'</a>'),'findings')
 b+=section(T('Qwen 4B 與 BGE-M3：多用容量，換到什麼？','Qwen 4B vs BGE-M3: what does extra capacity buy?'),p(T('兩組都搭 Qwen 0.6B 重排器，六項平均為0.862與0.860。一般五項為0.897與0.896；法律專項為0.684與0.682。法律候選 Recall@50 差約10個百分點，但57題的 Top-1 全部相同，nDCG逐題勝／負／平為13／13／31。找到更多候選，沒有等比例變成更好的最終排序。','Both use Qwen 0.6B reranking: six-task scores are 0.862 versus 0.860, general-five 0.897 versus 0.896, and legal 0.684 versus 0.682. Legal candidate Recall@50 differs by about ten percentage points, but Top-1 is identical on all 57 queries; nDCG wins/losses/ties are 13/13/31. Better candidate coverage does not translate proportionally into better final ranking.'))+p(T('Qwen 組多約3.395 GiB權重；重視英文檢索或候選覆蓋且容量有餘裕，才考慮升級。容量與中文搜尋優先時，BGE-M3組仍更划算。','The Qwen setup needs about 3.395 GiB more weights. Consider it for English retrieval or candidate coverage when capacity permits. BGE-M3 remains better value for memory efficiency and Chinese search.'))+'<a href="pair-comparison.html">'+T('看完整配對分析','See the full paired analysis')+' →</a>','pair-choice')
 b+=section(T('完整比較：切換分項、排序指標與重排器','Compare every setup: task, metric and reranker'),p(T('綠色是同一 Embedder 單用分數；橘色為重排提升，紅色斜線為下降。點選表格欄位可重新排序。','Teal shows the same embedder alone, orange a reranking gain, and red hatching a loss. Click any table heading to sort.'))+controls(lang)+'<p id="scope-note" class="note" aria-live="polite"></p><div class="phase-legend"><span class="base-key">'+T('單獨檢索','Embedding alone')+'</span><span class="gain-key">'+T('提升','Gain')+'</span><span class="loss-key">'+T('下降','Loss')+'</span></div><div id="phase-bars" aria-live="polite"></div><button id="toggle-bars" type="button" class="chart-toggle"></button><h3>'+T('28 種組合完整比較｜點欄位排序','All 28 setups | click a column to sort')+'</h3><div id="phase-table" class="table-scroll" tabindex="0"></div>'+p(T('六項總分不合併延遲，請切換分項看實測時間。一般五項時間為各項均時的等權平均；p50／p95僅呈現單一分項。ACORD新時間包含問題向量化、完整檢索、已標註篩選及重排，不含回答生成。','Latency is not pooled across all six tasks; select a task for measured timings. General-five latency equally weights task means; p50/p95 appear only for individual tasks. New ACORD timing includes query embedding, full search, judged filtering and reranking, excluding answer generation.')),'results')
 b+=recommendations(lang)
 winners=[]
 for d in ORDER:
  rows=group(d);best=rows[0]
  winners.append([previous.LABELS[d][lang],A['datasets'][d]['queries'],combo(best,lang),f'{best["ndcg10"]:.3f}',f'{max(r["top1"] for r in rows)*100:.2f}%'])
 b+=section(T('六個分項，各自比較','Compare each of the six tasks'),tab([T('分項','Task'),T('題數','Queries'),T('最高nDCG組合','Highest-nDCG setup'),'nDCG@10',T('分項最高Top-1¹','Best task Top-1¹')],winners)+p(T('¹最高Top-1可能來自另一組合。ACORD以3星以上為命中，使用已標註候選池；MIRACL是有限語料子集。各項不是相同難度的考試。','¹Best Top-1 may come from another setup. ACORD requires at least 3 stars and uses a judged candidate pool; MIRACL uses bounded corpus subsets. Task difficulties are not equivalent.')))
 b+=section(T('完整方法、模型與資料','Methods, models and data'),p('<a href="latest-methods.html">'+T('方法與下載','Methods and downloads')+'</a> · <a href="models.html">'+T('模型詳細頁面','Model details')+'</a> · <a href="'+pre+'data/matrix/current-summary.csv">'+T('最新168列CSV','Current 168-row CSV')+'</a>'))
 payload={'corrected':True,'retest':True,'lang':lang,'names':{k:name(k,lang) for k in A['names']},'labels':{k:v[lang] for k,v in previous.LABELS.items()},'datasets':A['datasets'],'scopes':{k:group(k) for k in ['all','general','mlqa']+ORDER}}
 b+='<script id="phase-data" type="application/json">'+json.dumps(payload,ensure_ascii=False).replace('</','<\\/')+'</script><script src="'+pre+'assets/phase2.js" defer></script>'
 return page('index.html',T('地端RAG中英檢索模型實測｜28種組合','28-setup bilingual retrieval benchmark'),b,lang)
def controls(lang):
 T=lambda z,e:t(z,e,lang)
 scopes=[('all',T('綜合平均｜六分項等權','Overall | six equal-weight tasks')),('general',T('一般／雙語｜原五項等權','General / bilingual | original five')),('mlqa',T('MLQA｜三方向等權','MLQA | three equal-weight directions'))]+[(d,previous.LABELS[d][lang]) for d in ORDER]
 options=[('scope',T('測試範圍','Test scope'),scopes),('metric',T('品質指標','Quality metric'),[('ndcg10','nDCG@10'),('top1','Top-1'),('mrr10','MRR@10'),('recall50','Recall@50')]),('reranker',T('顯示重排器','Show reranker'),[('all',T('全部28組','All 28 setups')),('standalone',T('不加重排器','No reranker'))]+[(k,name(k,lang)) for k in A['reranker_timing']])]
 return '<div class="controls">'+''.join('<label>'+label+f'<select id="{key}">'+''.join(f'<option value="{k}">{v}</option>' for k,v in opts)+'</select></label>' for key,label,opts in options)+'</div>'
def recommendations(lang):
 T=lambda z,e:t(z,e,lang)
 choices=[('granite-97m-r2','standalone',T('極小權重｜不到0.2 GiB','Tiny weights | under 0.2 GiB'),T('最小模型，適合建立低成本基線；品質明顯落後。','The smallest model provides a low-cost baseline, with lower quality.')),('embeddinggemma-2','standalone',T('輕量單模型｜不到0.5 GiB','Light single model | under 0.5 GiB'),T('不加重排，減少每次查詢等待。','Avoids per-query reranking latency.')),('bge-m3','standalone',T('低延遲單模型｜不到1 GiB','Low-latency single model | under 1 GiB'),T('此容量內純Embedder的六項綜合最高；法律單項另有不同排名。','Highest six-task standalone score within this weight budget; legal rankings differ.')),('bge-m3','qwen-reranker-0.6b',T('均衡配置｜不到1.5 GiB','Balanced setup | under 1.5 GiB'),T('此容量內六項綜合最高，適合作為一般與雙語搜尋起點。','Highest six-task score within this budget, a starting point for general and bilingual retrieval.')),('qwen-4b','qwen-reranker-0.6b',T('不到5 GiB的品質選擇','Quality under 5 GiB'),T('偏重英文檢索與候選覆蓋的升級選項，不是此容量內最高分。法律專項應同時比較Qwen 4B單用，避免多花時間反而降分。','An upgrade option for English retrieval and candidate coverage, not the highest score within this budget. For legal retrieval, also consider Qwen 4B alone: reranking here costs time and lowers nDCG.')),('qwen-4b','qwen-reranker-4b',T('品質優先｜不到8 GiB','Quality first | under 8 GiB'),T('六項0.886，接近整體最高0.887；4B重排器需明顯較長等待。','Six-task score 0.886, close to the leader at 0.887; 4B reranking requires substantially more time.'))]
 b=p(T('以下依容量與等待時間整理實用選項。權重 GiB 不是最低 RAM／VRAM；索引、工作緩衝與系統另需空間。其他硬體的速度與記憶體可行性尚未實測。','These options balance weight size and waiting time. Weight GiB is not minimum RAM/VRAM; indexes, buffers and the OS add overhead. Other hardware has not been benchmarked.'))+'<div class="recommend-grid">'
 for e,rr,title,why in choices:
  r=pick(e,rr);b+='<article class="scorecard"><h3>'+title+'</h3>'+p('<b>'+combo(r,lang)+'</b>')+p(f'nDCG {r["ndcg10"]:.3f} · Top-1 {r["top1"]*100:.2f}% · {r["weight_gib_sum"]:.3f} GiB')+p(why)+f'<a href="models/{e}.html">'+T('模型與完整配對','Model and all pairings')+' →</a></article>'
 return section(T('依容量與使用情境選擇','Choose by capacity and use case'),b+'</div>','choose')
def methods(lang):
 T=lambda z,e:t(z,e,lang);pre='../' if lang else ''
 b='<section class="phase-hero"><p class="eyebrow">METHODS / REPRODUCIBILITY</p><h1>'+T('測試怎麼做，結果能說到哪裡。','How the test works, and what it can establish.')+'</h1><p class="lead">'+T('原五項資料保留，ACORD以新候選協定完成28組重測。完整分項、數據與程式均可檢閱。','The original five tasks are retained; ACORD has a new 28-setup retest. Inspect all task scores, data and code.')+'</p></section>'
 sections=[('average',T('首頁平均如何計算？','How is the homepage mean calculated?'),T('先平均各分項的題目，再讓MLQA三方向、MIRACL兩語言、ACORD共六項各占1/6。六項分數＝（原五項平均×5＋ACORD）÷6。MLQA占50%、MIRACL占33.3%、法律占16.7%；這是指定權重，不是資料家族等權或實際查詢流量。保留原五項平均供切換。28組均須完整，不補零、不以題數混加。','Average queries within each task, then assign each of three MLQA directions, two MIRACL languages and ACORD weight 1/6. Six-task score = (original-five mean × 5 + ACORD) / 6. MLQA contributes 50%, MIRACL 33.3%, legal 16.7%; this is a chosen weighting, not equal dataset-family weighting or production traffic. The original-five mean remains selectable. All 28 setups are complete; missing scores are never zero-filled.')),
 ('fairness',T('相同題目、語料與候選數，具體是什麼？','What does consistent testing mean?'),T('同一分項的題目、語料、qrels與模型權重固定；每個Embedder的三個重排器共用有序Top50候選。不同Embedder候選可以不同。ACORD先按qrels是否存在排除未知配對，保留明確0分，再取Top50；其他五項直接取檢索Top50。ACORD這個候選條件在真實RAG不可得，因此綜合分數只代表本基準，不能解讀為部署命中率。','Queries, corpus, qrels and model weights are fixed within each task. Three rerankers share each embedder’s ordered Top50, while embedders may retrieve different candidates. ACORD first removes unknown qrel pairs, retaining explicit zero grades, then selects Top50; other tasks use unfiltered retrieval Top50. Production RAG lacks this judged-membership information, so the aggregate is a benchmark index, not a deployment hit rate.')),
 ('scope',T('資料範圍與雙語方向','Data scope and bilingual direction'),T('MLQA中文查英文504題、中文查中文504題、英文查英文1,148題；eng-zho指英文context／中文question，不是英文查中文。MIRACL每語言200題，中文語料3,786篇、英文7,921篇，是dev已標註段落聯集而非百萬級完整語料。ACORD為57題、3,931條款、61,988標註配對，revision 7ba1c6f2e0baaa32e78c78c2b02e9c57b102af4e。最新73,164筆＝原五項71,568＋新ACORD 1,596；不是獨立樣本數。','MLQA: 504 Chinese-to-English, 504 Chinese-to-Chinese and 1,148 English-to-English queries. eng-zho means English context / Chinese question, not the reverse. MIRACL has 200 queries per language with 3,786 Chinese and 7,921 English passages, a union of dev-judged passages rather than full million-scale corpora. ACORD has 57 queries, 3,931 clauses and 61,988 judged pairs at revision 7ba1c6f2e0baaa32e78c78c2b02e9c57b102af4e. Current rows total 73,164 = 71,568 retained + 1,596 retested; this is not the independent sample count.')),
 ('timing',T('時間包含什麼？','What does latency include?'),T('原五項包含問題向量化＋檢索＋重排；ACORD新測另明列已標註候選篩選。熱查詢時間不含模型載入、索引建立與回答生成；loopback HTTP包含在模型階段。各項展示mean／p50／p95，不直接平均百分位數；六項總表不混合時間。全部為一次正式逐題測量，不是固定30題×3次壓測，不能保證真實服務延遲。權重相同，歷史runtime library雜湊未全部可追溯。','Original-five timing includes query embedding, search and reranking; new ACORD timing separately includes judged filtering. Warm timing excludes model loading, indexing and answer generation; loopback HTTP is included in model stages. Individual tasks show mean/p50/p95, without averaging percentiles. Six-task latency is not pooled. One accepted measurement per query is not a fixed 30-query × 3-repeat load test and cannot guarantee production latency. Weights match, but not all historical runtime-library hashes are available.')),
 ('uncertainty',T('小差距能代表勝出嗎？','Do small differences establish a winner?'),T('六項前兩名只差約0.0006；ACORD多個4B重排組合也很接近。沒有全域bootstrap或多重比較校正，不宣稱顯著或穩定勝出。ACORD的來源問題群聚未能確認，未新增其bootstrap區間；原五項配對分析的區間不延伸成六項結論。資料集、候選限制與任務權重都可能影響名次。','The leading six-task scores differ by about 0.0006; several ACORD 4B-reranker scores are also close. No global bootstrap or multiplicity adjustment supports a reliable/significant winner. ACORD source-query dependence is unverified, so no new bootstrap interval is reported; original-five paired intervals do not extend to the six-task index. Datasets, candidate constraints and task weights affect rankings.'))]
 for ident,h,text in sections:b+=section(h,p(text),ident)
 # Retain the previously sourced comparison with official evaluations.
 prior=previous.methods(lang)
 match=re.search(r'<section id="published">.*?</section>',prior,re.S)
 if match:b+=match.group(0)
 b+=section(T('驗證結果與已知限制','Verification and known limitations'),p(T('本次重新核對102個來源檔案雜湊、十個模型權重、完整題目／語料／qrels，並通過獨立逐題數值驗證：28組、1,596題次、399候選清單、59,850配對分數；缺漏、重複、非有限值與接受結果錯誤皆0。原交付有69份舊judged尾段排名差異，均在Top50外，其中4份超過診斷epsilon；來源未明，不能斷言是浮點誤差。','Publication checks verified 102 source-file hashes, ten model weights and all queries/corpus/qrels. Independent per-query validation passed: 28 setups, 1,596 rows, 399 candidate lists, 59,850 pair scores; no missing, duplicate, nonfinite or accepted-error rows. The source reports 69 historical judged-tail differences, all beyond Top50, four above the diagnostic epsilon; their cause is unresolved, not established as floating-point noise.'))+p(T('交付環境macOS報告107測試通過；目前Windows重查為87個測試通過、7個測試模組因Unix fcntl依賴無法載入。資料驗證器可在Windows通過；本次網頁更新沒有重新執行模型推論。','The delivered macOS environment reports 107 passing tests. This Windows recheck passed 87 tests, with seven test modules unable to import Unix fcntl dependencies. The data validator passes on Windows; publication work did not rerun model inference.')),'verification')
 b+=section(T('完整資料、程式與素材下載','Complete data, code and materials'),p('<a href="'+pre+'downloads/acord-retest-20261027.zip">'+T('ACORD重測完整套件：103檔，含程式、素材、排名與全部結果','ACORD retest: 103 files including code, materials, rankings and every result')+'</a>')+p('<a href="'+pre+'data/acord/publication-validation.json">'+T('本次獨立驗證','Publication validation')+'</a> · <a href="'+pre+'data/acord/summary.csv">ACORD CSV</a> · <a href="'+pre+'data/matrix/current-summary.csv">'+T('最新六項168列CSV','Current six-task 168-row CSV')+'</a> · <a href="'+pre+'data/matrix/current-comparison.json">'+T('六項／五項／單項JSON','Six-task / five-task / individual JSON')+'</a>')+p(T('解壓ACORD套件後可執行 python -m src.independent_validate .；不需要模型。完整測試與施測控制器使用macOS／Unix。原五項程式及七批逐題結果保留在下列檔案；原ZIP也含歷史ACORD，不能誤當最新分數。','After extracting ACORD, run python -m src.independent_validate . without models. Full tests and the measurement controller require macOS/Unix. Original-five code and seven raw batches remain below; those archives also contain historical ACORD and are not the latest legal scores.'))+'<div class="downloads">'+''.join(f'<a class="download" href="{pre}downloads/matrix-B{i:02}-results.zip">B{i:02} · '+T('原始逐題結果','Original per-query results')+'</a>' for i in range(1,8))+'</div>'+p('<a href="'+pre+'downloads/matrix-code.zip">'+T('原矩陣程式','Original matrix code')+'</a> · <a href="'+pre+'downloads/matrix-shared.zip">'+T('原共同選題與qrels','Original selection and qrels')+'</a> · <a href="'+pre+'downloads/phase2-materials.zip">'+T('凍結素材','Frozen materials')+'</a> · <a href="'+pre+'data/SHA256SUMS.json">SHA256</a>'),'downloads')
 b+=section(T('授權、版本與歷史','Licenses, versions and history'),p(T('MLQA：CC BY-SA 3.0；ACORD：CC BY 4.0；MIRACL topics/qrels：Apache 2.0，文章全文依上游適用授權。保留來源與改作說明；程式MIT不取代資料或模型授權。ACORD包保留凍結全文素材，未包含模型權重、向量快取、私有憑證或完整runtime logs。原研究報告以法律獨立專項交付；本站在驗證後新增六項等權指標，未改寫封存報告。','MLQA: CC BY-SA 3.0; ACORD: CC BY 4.0; MIRACL topics/qrels: Apache 2.0, with corpus text subject to upstream terms. Attribution and adaptation notes are retained; MIT code licensing does not replace data/model licenses. ACORD includes frozen text materials, excluding weights, vector caches, private credentials and full runtime logs. Its archived report treats legal retrieval separately; this site adds the verified six-task index without rewriting that report.'))+p('<a href="https://huggingface.co/datasets/theatticusproject/acord">ACORD / The Atticus Project</a> · <a href="https://github.com/facebookresearch/MLQA">MLQA</a> · <a href="https://github.com/project-miracl/miracl">MIRACL</a> · <a href="phase2.html">'+T('10/24歷史版本','Oct 24 historical release')+'</a> · <a href="baseline.html">'+T('10/22歷史版本','Oct 22 historical release')+'</a>'),'license')
 return page('latest-methods.html',T('地端RAG：方法、限制與完整資料','Local RAG: methods, limitations and data'),b,lang)
def acord(lang):
 T=lambda z,e:t(z,e,lang);pre='../' if lang else ''
 b='<section class="phase-hero"><p class="eyebrow">ACORD / 28-SETUP RETEST</p><h1>'+T('法律條款檢索：重排不是保證進步。','Legal-clause retrieval: reranking is not a guaranteed improvement.')+'</h1><p class="lead">'+T('57題、3,931條款、28組完整重測。先看排名品質，再看高星等條款與等待時間。','57 queries, 3,931 clauses and 28 complete retested setups. Compare ranking quality, high-star clauses and waiting time.')+'</p></section>'
 b+=section(T('如何閱讀這次結果？','How should these results be read?'),p(T('本次先排除未標註配對、保留明確0分，再取前50篇供三個重排器共用。線性nDCG以完整qrels計算理想排名；Top-1以3星以上判定。這是受控的judged-top50-v1協定，不能當成一般RAG的端到端命中率。','Unknown qrel pairs are removed, explicit zero grades retained, then Top50 is shared by three rerankers. Linear nDCG uses full-qrels ideal rankings; Top-1 requires at least 3 stars. This controlled judged-top50-v1 protocol is not a production RAG hit rate.'))+p(T('最高nDCG點估計是F2LLM 0.6B＋Qwen 4B：0.729。小型Embedder配4B重排雖能得到接近領先的法律成績，重排約需數秒，不因此列為一般用途的容量首選。','F2LLM 0.6B + Qwen 4B has the highest nDCG estimate at 0.729. A small embedder with 4B reranking can approach leading legal scores, but takes several seconds and is not thereby the default capacity recommendation.')))
 b+=section(T('完整28組法律結果','All 28 legal results'),tab([T('組合','Setup'),'nDCG@10','Top-1','4★ P@5','5★ P@5',T('候選Recall@50','Candidate Recall@50'),T('均時／p50／p95 秒','Mean / p50 / p95 s')],[[combo(r,lang),f'{r["ndcg10"]:.3f}',f'{r["top1"]*100:.2f}%',f'{r["p5_stars4"]*100:.2f}%',f'{r["p5_stars5"]*100:.2f}%',f'{r["recall50"]*100:.2f}%',f'{r["total_ms_mean"]/1000:.2f} / {r["total_ms_p50"]/1000:.2f} / {r["total_ms_p95"]/1000:.2f}'] for r in group('acord-eng-eng')])+p(T('星等P@5使用min(5,該星等以上條款數)正規化；5星有29題可評，其他無符合條款的題目排除，不補零。不是法律答案正確率。時間包含向量化、檢索、已標註篩選與重排。','Star P@5 divides by min(5, count of qualifying clauses); 5-star has 29 eligible queries, excluding queries without qualifying clauses rather than zero-filling. It is not legal answer accuracy. Time includes embedding, search, judged filtering and reranking.')))
 b+=section(T('為什麼需要依任務選重排器？','Why choose rerankers by task?'),p(T('Qwen 4B單用為0.703，BGE重排後0.675、Qwen 0.6B重排後0.684、Qwen 4B重排後0.728。相同候選池下，小重排器可能把高品質條款往後移，並非模型越多就越好。','Qwen 4B alone scores 0.703; BGE reranking gives 0.675, Qwen 0.6B gives 0.684, and Qwen 4B gives 0.728. On the same candidate pool, a small reranker may move high-quality clauses down; adding models does not guarantee improvement.'))+p(T('Qwen 4B與BGE-M3都搭Qwen 0.6B時，nDCG為0.684與0.682；候選召回95.26%與85.30%，但Top-1同為66.67%，57題逐題皆相同。多找回候選不等於最終排名一定提升。','With Qwen 0.6B reranking, Qwen 4B and BGE-M3 score 0.684 and 0.682; candidate recall is 95.26% versus 85.30%, yet Top-1 is 66.67% and identical query-by-query. More candidate coverage does not guarantee better final ranking.'))+'<a href="pair-comparison.html">'+T('配對分析與容量取捨','Paired analysis and capacity tradeoffs')+'</a>')
 prior=previous.acord(lang);match=re.search(r'<section id="published">.*?</section>',prior,re.S)
 if match:b+=match.group(0)
 b+=section(T('驗證、重現與限制','Verification, reproduction and limitations'),p(T('新結果已核對完整排名、候選雜湊、全部重排分數、逐題指標及時間加總。只代表57題與指定候選協定；沒有統計顯著勝出或服務壓力測試的結論。歷史尾段排名差異與Windows測試相容性限制另見方法頁。','Full rankings, candidate hashes, every reranker score, query metrics and timing sums were validated. Results cover only 57 queries and this candidate protocol, without significant-winner or service-load claims. Historical tail-ranking discrepancies and Windows test limitations are documented in Methods.'))+p('<a href="'+pre+'downloads/acord-retest-20261027.zip">'+T('完整重測程式、素材與結果ZIP','Complete retest code, materials and results ZIP')+'</a> · <a href="latest-methods.html#verification">'+T('驗證與限制','Verification and limitations')+'</a> · <a href="'+pre+'data/acord/publication-validation.json">'+T('獨立驗證JSON','Independent validation JSON')+'</a>'),'downloads')
 return page('acord.html',T('ACORD法律條款｜28組重測結果','ACORD legal retrieval | 28 retested setups'),b,lang)
def build():
 for lang in (0,1):
  folder=R/('en' if lang else '');T=lambda z,e:t(z,e,lang)
  for path,render in [('index.html',home),('latest-methods.html',methods),('acord.html',acord)]: (folder/path).write_text(render(lang),encoding='utf8')
  for model in (folder/'models').glob('*.html'):
   s=model.read_text('utf8');key=model.stem;rows=[r for d in ORDER for r in group(d) if key in (r['embedding'],r['reranker'])]
   start=s.index('<main id="main">')+len('<main id="main">');marker=T('<h2>模型介紹與10/22歷史結果</h2>','<h2>Model background and Oct 22 historical results</h2>');end=s.index(marker,start)
   body='<aside class="note">2026-10-28 · <a href="../index.html">'+T('最新六項綜合比較','Current six-task comparison')+'</a> · <a href="../acord.html">ACORD</a> · <a href="../latest-methods.html">'+T('方法與下載','Methods and downloads')+'</a></aside>'
   body+=section(T('最新完整配對結果','Current results for every pairing'),p(T('ACORD為已標註候選池的獨立重測；各分項的語料與評分條件不同，請依用途比較。時間包含所選重排器，ACORD另含評估篩選。','ACORD was retested with a judged candidate pool. Corpora and scoring conditions differ across tasks; compare by use case. Timing includes the selected reranker and, for ACORD, evaluation filtering.'))+tab([T('分項','Task'),T('組合','Setup'),'nDCG@10','Top-1','Recall@50',T('均時 秒','Mean s')],[[previous.LABELS[r['dataset']][lang],combo(r,lang),f'{r["ndcg10"]:.3f}',f'{r["top1"]*100:.2f}%',f'{r["recall50"]*100:.2f}%',f'{r["total_ms_mean"]/1000:.3f}'] for r in rows]))
   model.write_text(s[:start]+body+s[end:],encoding='utf8')
  pair=folder/'pair-comparison.html';s=pair.read_text('utf8')
  s=s.replace(T('ACORD重排修正尚未完成，因此不能拿舊法律分數替升級背書。','Corrected ACORD reranking is pending, so old legal scores cannot justify upgrading.'),T('ACORD另有新測57題，結果與限制見本頁法律補充。','A separate 57-query ACORD retest is reported in the legal supplement below.'))
  extra=section(T('新增法律分項後，升級理由有改變嗎？','Does adding legal retrieval change the upgrade case?'),p(T('六項綜合nDCG為Qwen組0.862、BGE組0.860。ACORD單項為0.684與0.682，逐題勝／負／平13／13／31；Top-1的57題全部相同。Qwen的候選Recall@50為95.26%，BGE為85.30%，但最終排序差距仍小。沒有足夠證據把額外3.395 GiB權重說成普遍值得的升級。','Six-task nDCG is 0.862 for Qwen versus 0.860 for BGE. ACORD alone scores 0.684 versus 0.682, with 13/13/31 query wins/losses/ties; all 57 Top-1 scores match. Candidate Recall@50 is 95.26% versus 85.30%, but final ranking differs only slightly. This does not establish a general case for the extra 3.395 GiB of weights.'))+p(T('上方2,556題與bootstrap仍只針對原五項，沒有把57題法律結果混入原區間。ACORD來源問題群聚未確認，因此沒有新增法律bootstrap。','The 2,556-query comparison and bootstrap above still cover only the original five tasks; 57 legal queries are not mixed into those intervals. No legal bootstrap was added because source-query clustering is unverified.'))+'<a href="acord.html">'+T('法律完整結果','Full legal results')+'</a>')
  pair.write_text(s.replace('</main>',extra+'</main>'),encoding='utf8')
  for fn in ['models.html','methods.html','resources.html']:
   fp=folder/fn;s=fp.read_text('utf8');s=s.replace('2026-10-26 完整28組矩陣','2026-10-28 六項綜合與ACORD重測').replace('Complete 28-setup matrix · 26 Oct 2026','Six-task comparison and ACORD retest · 28 Oct 2026');fp.write_text(s,encoding='utf8')
 current={'version':'2026-10-28-acord-retest','aggregation':'Six task means with equal weight 1/6; general retains the original five at 1/5. ACORD uses judged-top50-v1. Six-task latency is not pooled.','scopes':{k:group(k) for k in ['all','general','mlqa']+ORDER}}
 (R/'data/matrix/current-comparison.json').write_text(json.dumps(current,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
 fields=['dataset','embedding','reranker','queries','top1','ndcg10','mrr10','recall50','p5_stars4','p5_stars5','total_ms_mean','total_ms_p50','total_ms_p95','weight_gib_sum','protocol']
 with (R/'data/matrix/current-summary.csv').open('w',encoding='utf-8-sig',newline='') as f:
  w=csv.DictWriter(f,fields,extrasaction='ignore');w.writeheader()
  for d in ORDER:
   for r in group(d):w.writerow(dict(r,dataset=d,protocol='judged-top50-v1' if d=='acord-eng-eng' else 'original-binary-top50'))
 for fp in R.rglob('*.html'):
  s=fp.read_text('utf8')
  if fp.name not in ['baseline.html','phase2.html','phase2-methods.html']:
   s=re.sub(r'最新測量完成：[^<]*','最新結果更新：2026-10-28（臺灣時間）',s)
   s=re.sub(r'Latest measurements completed:[^<]*','Results updated: 28 Oct 2026 Taipei',s)
  for asset in ['assets/style.css','assets/phase2.css','assets/phase2.js']:s=re.sub(re.escape(asset)+r'(?:\?v=[^"\s]+)?"',asset+'?v=20261028-acord-v1"',s)
  fp.write_text(s,encoding='utf8')
 sitemap=R/'sitemap.xml';sitemap.write_text(sitemap.read_text('utf8').replace('2026-10-27','2026-10-28'),encoding='utf8')
 print('Published current six-task builder: 28 configurations, 168 task rows')
